#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // We want to move element from pos to placed
        // Strategy: use suffix containing just element at pos, prefix = placed
        // But we need x+y < n, x=placed, y=n-pos... placed+(n-pos)<n => placed<pos, which is true since pos>placed
        // Also x>0 requires placed>0, and y>0 requires pos<n which is true

        if(placed > 0 && placed < pos) {
            // Direct: x=placed, y=n-pos
            int x = placed, y = n - pos;
            ops.push_back({x, y});
            apply(p, x, y);
        } else {
            // placed==0, so x must be >0. First move element to last position.
            if(pos < n-1) {
                // x=pos+1, y=1, need pos+2<n => pos<n-2
                // Or: x=1, y=n-1-pos, need 1+n-1-pos<n => pos>0 (true since pos>placed=0)
                int x = 1, y = n - pos;
                // x+y = 1+n-pos < n iff pos > 1... if pos==1, x+y=n not valid
                if(x + y < n) {
                    ops.push_back({x, y});
                    apply(p, x, y);
                    // element now at position 0 = placed, done
                    continue;
                }
                // pos==1: use x=2, y=n-2 if n>3
                x = pos + 1; y = 1;
                if(x > 0 && y > 0 && x + y < n) {
                    ops.push_back({x, y});
                    apply(p, x, y);
                    pos = n - 1;
                }
            }
            // Now element at pos=n-1, placed=0: x must be >0 but placed=0
            // Use x=1, y=1: moves last to front, first to back
            if(p[n-1] == placed+1) {
                int x=1, y=1;
                ops.push_back({x,y});
                apply(p,x,y);
                // Check if placed now
                if(p[0]==placed+1) continue;
            }
            // Fallback: find it again
            for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            if(pos==placed) continue;
            if(placed>0) {
                int x=placed, y=n-pos;
                if(x>0&&y>0&&x+y<n){ops.push_back({x,y});apply(p,x,y);continue;}
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
